"""Create original teacher activity packs and remediation cards, not copies of source pages."""
import json,html
from pathlib import Path
root=Path(__file__).resolve().parents[1]
lessons=json.loads((root/'src/data/nuclear-learning.json').read_text())
configs={
'B21':dict(approach='Khởi động bằng nhận định về nguyên tử, yêu cầu dự đoán đường hạt α. Nhóm thay đổi khoảng cách hạt tới tâm, so sánh góc nhìn và viết lập luận từ kết quả. Chốt Z, N, A rồi dùng các đồng vị carbon để kiểm tra cách hiểu.',support='Cung cấp bảng ba cột Z–N–A cho học sinh cần hỗ trợ; nhóm hoàn thành sớm so sánh tỉ số bán kính theo A^(1/3).',product='Bảng quan sát Rutherford và bảng Z–N–A của ba đồng vị.',misconceptions=[('Đồng vị có cùng số khối A.','Đồng vị có cùng Z, khác N nên khác A. Hãy so sánh C-12, C-13 và C-14.'),('Hạt α lệch mạnh vì va vào electron.','Lập luận Rutherford gắn với vùng điện tích dương và khối lượng tập trung trong hạt nhân nhỏ.'),('Bán kính hạt nhân tăng gấp đôi nếu A tăng gấp đôi.','R tỉ lệ A^(1/3), nên tỉ số là 2^(1/3), khoảng 1,26.')]),
'B22':dict(approach='Nhóm cân bằng A và Z trước khi tìm hạt còn thiếu. Tiếp theo đối chiếu quy ước khối lượng nguyên tử/hạt nhân, tính Δm, E liên kết và E/A. Dùng cảnh phân hạch và D–T để giải thích năng lượng tỏa ra.',support='Cho nhóm cần hỗ trợ mẫu bảng tổng A, Z; nhóm nâng cao so sánh Q của phản ứng với năng lượng liên kết của từng hạt nhân.',product='Hai phương trình cân bằng, một bài tính có đơn vị và lời giải thích phân hạch/tổng hợp.',misconceptions=[('Năng lượng liên kết tổng càng lớn thì luôn càng bền.','Để so sánh mức liên kết trung bình, xem E liên kết riêng E/A; không so sánh chỉ tổng E.'),('Tổng khối lượng nghỉ được bảo toàn trong mọi phản ứng.','Năng lượng toàn phần được bảo toàn; chênh lệch khối lượng nghỉ có thể chuyển thành động năng hoặc bức xạ.'),('Ví dụ D–T là chuỗi phản ứng chính trong Mặt trời.','D–T là ví dụ hợp nhất dùng trong bài; chuỗi proton–proton giữ vai trò chính trong Mặt trời.')]),
'B23':dict(approach='Trước lớp học sinh dự đoán N sau 1T, 2T, 3T. Trong lớp quan sát 64 hạt, đối chiếu số kì vọng với đồ thị và lặp số đếm Geiger. Nhóm giải thích sự khác nhau giữa quy luật thống kê và thời điểm phân rã từng hạt.',support='Cung cấp bảng N₀, N₀/2, N₀/4 cho nhóm cần hỗ trợ; nhóm nâng cao suy T từ hai điểm và phân biệt H với N.',product='Bảng N(t), đường cong, giải thích sự ngẫu nhiên và bản sửa dự đoán.',misconceptions=[('Sau một T, tất cả các hạt đều đã phân rã.','Sau T, kì vọng còn N₀/2 hạt nhân mẹ. Sau 3T vẫn còn N₀/8.'),('Mỗi giây máy đếm bắt buộc phải ghi nhận một hạt.','Số đếm ngẫu nhiên có thể bằng 0; so sánh nhiều lượt thay vì suy từ một lượt.'),('N và H có cùng đơn vị.','N là số hạt nhân, H = λN có đơn vị Bq; λ có đơn vị s⁻¹ khi T theo giây.')]),
'B24':dict(approach='Nhóm theo dõi dòng năng lượng qua lò, bộ trao đổi nhiệt, turbine và máy phát. Sau đó chia vai nghiên cứu y học, thực phẩm, công nghiệp; phân biệt mục tiêu, cơ chế, lợi ích và giới hạn. Dùng đóng vai để phản biện dựa trên nguồn.',support='Cho nhóm cần hỗ trợ thẻ “nguồn–cơ chế–mục tiêu”; nhóm nâng cao đối chiếu PET với SPECT và xạ trị, ghi nguồn cho từng kết luận.',product='Sơ đồ dòng năng lượng và bảng ứng dụng có nguồn, lợi ích, giới hạn.',misconceptions=[('Hai vòng nước trong nhà máy phải trộn với nhau để truyền nhiệt.','Bộ trao đổi nhiệt truyền năng lượng qua bề mặt ngăn cách; hai vòng nước tách biệt trong mô hình.'),('PET và xạ trị có cùng mục tiêu.','PET dùng ghi hình từ chất đánh dấu; xạ trị tác động năng lượng lên mô đích để điều trị.'),('Chiếu xạ đúng quy trình biến thực phẩm thành nguồn phóng xạ.','Chiếu xạ bảo quản không đồng nghĩa tạo phóng xạ trong thực phẩm; không suy quy trình an toàn từ màu hay hoạt cảnh.')]),
'B25':dict(approach='Nhóm phân tích bảng H(t) của SGK, xác định H₀/2 rồi tìm khoảng chứa T. Dùng notebook hoặc bảng tính để so sánh mô hình; yêu cầu ghi dữ liệu nguồn, giả thiết, đơn vị và lí do sai khác. Cuối cùng chọn đề mẫu phù hợp tiến độ.',support='Cung cấp trục và mức H₀/2 cho nhóm cần hỗ trợ; nhóm nâng cao ước lượng T từ nhiều cặp điểm rồi so sánh độ nhạy.',product='Bảng, đồ thị có đơn vị; khoảng/ước lượng T và giải thích sai số.',misconceptions=[('H(30 s) = 85 Bq, nên T = 30 s khi H₀ = 151 Bq.','Mức bán rã là 75,5 Bq; 85 Bq chưa tới mức đó. Với H(60 s) = 55 Bq, suy ra 30 s < T < 60 s.'),('Phải chỉnh số liệu để mọi điểm khớp đường mũ.','Giữ dữ liệu gốc, ghi sai số và cách khớp; không thay dữ liệu để đẹp đồ thị.'),('Đường mô phỏng mượt chính là kết quả đo mới.','Đường mô phỏng là giá trị từ mô hình; bảng SGK có nguồn riêng. Báo cáo phải phân biệt hai loại dữ liệu.')])}
guides=[]
for l in lessons:
 c=configs[l['code']]
 guides.append(dict(code=l['code'],title=l['title'],goals=l['goals'],before=l['before'],during=l['during'],after=l['after'],**c))
rubric=[
dict(id='goal',title='Xác định mục tiêu và lập kế hoạch',evidence='Mục tiêu, thời lượng dự kiến và học liệu đã chọn.',levels=['Chưa nêu mục tiêu cụ thể.','Nêu mục tiêu nhưng chưa có cách thực hiện.','Nêu mục tiêu, chọn học liệu và phân chia thời gian.','Điều chỉnh mục tiêu/kế hoạch có lí do sau khi đối chiếu kết quả.']),
dict(id='monitor',title='Theo dõi và kiểm tra cách hiểu',evidence='Dự đoán, bảng quan sát, kết quả tự kiểm tra.',levels=['Chưa có bản ghi quan sát.','Có bản ghi nhưng chưa đối chiếu dự đoán.','Đối chiếu dự đoán với quan sát và chỉ ra sai khác.','Chủ động lặp/thay đổi điều kiện và kiểm tra lại lập luận.']),
dict(id='evidence',title='Giải thích và sử dụng nguồn',evidence='Lời giải có công thức, đơn vị và nguồn.',levels=['Nêu kết quả chưa giải thích.','Có giải thích nhưng thiếu căn cứ hoặc đơn vị.','Dùng căn cứ vật lí, đơn vị và nguồn phù hợp.','So sánh nguồn/mô hình, nêu giả thiết và giới hạn kết luận.']),
dict(id='adjust',title='Tự đánh giá và điều chỉnh',evidence='Bản sửa lỗi và hành động học tiếp.',levels=['Chưa xác định điều cần sửa.','Nêu khó khăn chung chung.','Chỉ ra lỗi cụ thể và đề xuất hành động sửa.','Thực hiện sửa, kiểm tra kết quả và ghi bước tiếp theo.'])]
(root/'src/data/teaching-guides.json').write_text(json.dumps(dict(guides=guides,rubric=rubric),ensure_ascii=False,indent=2))
out=root/'public/learning/guides';out.mkdir(parents=True,exist_ok=True)
esc=html.escape
style='<style>body{font:16px Arial,sans-serif;line-height:1.6;max-width:850px;margin:32px auto;padding:0 24px}h1{font-size:26px}li{margin:8px 0}section{break-inside:avoid}@media print{body{margin:0;max-width:none}}</style>'
for g in guides:
 body=f'<h1>{g["code"]} {esc(g["title"])} — Gợi ý tổ chức dạy học</h1><p>Giáo viên điều chỉnh theo lớp, thời lượng và điều kiện thiết bị. Hướng dẫn chưa phải kế hoạch đã thử nghiệm với học sinh.</p><h2>Mục tiêu</h2><ul>'+''.join(f'<li>{esc(s)}</li>' for s in g['goals'])+'</ul>'
 body+=f'<h2>Cách tổ chức</h2><p>{esc(g["approach"])}</p><h2>Phân hóa</h2><p>{esc(g["support"])}</p><h2>Sản phẩm và căn cứ đánh giá</h2><p>{esc(g["product"])}</p>'
 for key,label in [('before','Trước giờ'),('during','Trong giờ'),('after','Sau giờ')]:body+=f'<h2>{label}</h2><ol>'+''.join(f'<li>{esc(s)}</li>' for s in g[key])+'</ol>'
 body+='<h2>Sửa lỗi thường gặp</h2>'+''.join(f'<section><h3>{esc(a)}</h3><p>{esc(b)}</p></section>' for a,b in g['misconceptions'])
 body+='<h2>Quan sát tự học</h2><p>Các chỉ báo dùng để thiết kế/phản tư, chưa là thang đo đã kiểm định.</p>'+''.join(f'<h3>{esc(r["title"])}</h3><p>{esc(r["evidence"])}</p><ol>'+''.join(f'<li>{esc(s)}</li>' for s in r['levels'])+'</ol>' for r in rubric)
 body+='<p>Tài liệu tham khảo: Vật lí 12 – Kết nối tri thức với cuộc sống, Chương IV, Nhà xuất bản Giáo dục Việt Nam.</p>'
 (out/f'{g["code"]}.html').write_text('<!doctype html><html lang="vi"><meta charset="utf-8">'+style+'<body>'+body+'</body></html>')
(out/'self-learning-rubric.html').write_text('<!doctype html><html lang="vi"><meta charset="utf-8">'+style+'<body><h1>Phiếu quan sát và phản tư năng lực tự học</h1><p>Khung đề xuất theo bài báo; cần thẩm định trước sử dụng làm công cụ nghiên cứu.</p>'+''.join(f'<h2>{esc(r["title"])}</h2><p>{esc(r["evidence"])}</p><ol>'+''.join(f'<li>{esc(s)}</li>' for s in r['levels'])+'</ol><p>Bằng chứng ......................................................................................................</p>' for r in rubric)+'</body></html>')
print('5 teacher packs, 15 remediation cards, 4 rubric criteria, 6 printable HTML files')
